#!/usr/bin/env bash
# bootstrap-from-lovable.sh
# Self-contained bootstrap that writes the real Librosa MCP deploy kit into the
# CURRENT directory. Run on EC2 from inside ~/sam-api/librosa-mcp (or any empty dir).
#
# Usage:
#   cd ~/sam-api/librosa-mcp
#   bash bootstrap-from-lovable.sh
#
# After it succeeds, run:
#   sudo HOSTNAME=<your.duckdns.org> EMAIL=<real@email.com> ./install.sh

set -euo pipefail

echo "[bootstrap] Clearing any stale/corrupted files in $(pwd) ..."
rm -f install.sh smoke-test.sh server_extended.py librosa-mcp.service nginx-librosa-mcp.conf README.md

decode() {
  local name="$1"
  local b64="$2"
  echo "[bootstrap] Writing $name ..."
  echo "$b64" | base64 -d > "$name"
}

decode 'install.sh' ''

decode 'smoke-test.sh' ''

decode 'server_extended.py' ''

decode 'librosa-mcp.service' ''

decode 'nginx-librosa-mcp.conf' ''

decode 'README.md' ''


chmod +x install.sh smoke-test.sh

echo ""
echo "================================================================"
echo "  Bootstrap complete. Files in $(pwd):"
ls -la install.sh smoke-test.sh server_extended.py librosa-mcp.service nginx-librosa-mcp.conf README.md
echo ""
echo "  Next step (replace HOSTNAME + EMAIL with real values):"
echo ""
echo "    sudo HOSTNAME=samc-librosa.duckdns.org \\"
echo "         EMAIL=sam.chernoff@gmail.com \\"
echo "         ./install.sh"
echo "================================================================"
